   320  /**
   321   * Internal function - initialize the iterator without stepping to the first
   322   * value
   323   */
   324  static IterCellsPolygonCompact _iterInitPolygonCompact(
   325      const GeoPolygon *polygon, int res, uint32_t flags) {
   326      IterCellsPolygonCompact iter = {// Initialize output properties. The first
   327                                      // valid cell will be set in iterStep
   328                                      .cell = baseCellNumToCell(0),
   329                                      .error = E_SUCCESS,
   330                                      // Save input arguments
   331                                      ._polygon = polygon,
   332                                      ._res = res,
   333                                      ._flags = flags,
   334                                      ._bboxes = NULL,
   335                                      ._started = false};
   336
   337      if (res < 0 || res > MAX_H3_RES) {
   338          iterErrorPolygonCompact(&iter, E_RES_DOMAIN);
   339          return iter;
   340      }
   341
   342      H3Error flagErr = validatePolygonFlags(flags);
   343      if (flagErr) {
   344          iterErrorPolygonCompact(&iter, flagErr);
   345          return iter;
   346      }
   347
   348      // Initialize bounding boxes for polygon and any holes. Memory allocated
   349      // here must be released through iterDestroyPolygonCompact
   350      iter._bboxes = H3_MEMORY(calloc)((polygon->numHoles + 1), sizeof(BBox));
   351      if (!iter._bboxes) {
   352          iterErrorPolygonCompact(&iter, E_MEMORY_ALLOC);
   353          return iter;
   354      }
   355      bboxesFromGeoPolygon(polygon, iter._bboxes);
   356
   357      return iter;
   358  }
