   648   * @param  iter Iterator to increment
   649   */
   650  void iterStepPolygon(IterCellsPolygon *iter) {
   651      if (iter->cell == H3_NULL) return;
   652
   653      // See if there are more children to output
   654      iterStepChild(&(iter->_childIter));
   655      if (iter->_childIter.h) {
   656          iter->cell = iter->_childIter.h;
   657          return;
   658      }
   659
   660      // Otherwise, increment the polyfill iterator
   661      iterStepPolygonCompact(&(iter->_cellIter));
   662      if (iter->_cellIter.cell) {
   663          _iterInitParent(iter->_cellIter.cell, iter->_cellIter._res,
   664                          &(iter->_childIter));
   665          iter->cell = iter->_childIter.h;
   666          return;
   667      }
   668
   669      // All done, set to null and report errors if any
   670      iter->cell = H3_NULL;
   671      iter->error = iter->_cellIter.error;
   672  }
